/**
 * Demo data seeder (idempotent): six fictional customers, one support agent, one administrator and
 * two months of synthetic activity (salary, card purchases, rent, savings, scheduled payments,
 * pending transfers and support tickets).
 *
 * - No real personal data: every person, address and phone number below is fictional (T544).
 * - No hardcoded passwords: DEMO_USER_PASSWORD must be provided per environment (T76, T49).
 * - Users are created through the Auth Admin API, so Supabase Auth hashes the passwords (T60).
 * - The ledger baseline is generated by public.sim_seed_baseline() via sim_reset_demo_data(), the same
 *   code path the admin "Reset data" button uses.
 *
 * Usage: pnpm seed:demo   (reads .env.local when present)
 */
import { createClient } from "@supabase/supabase-js";

const url = process.env.NEXT_PUBLIC_SUPABASE_URL;
const serviceKey = process.env.SUPABASE_SERVICE_ROLE_KEY;
const demoPassword = process.env.DEMO_USER_PASSWORD;

if (!url || !serviceKey || !demoPassword || demoPassword.length < 12) {
  console.error("Set NEXT_PUBLIC_SUPABASE_URL, SUPABASE_SERVICE_ROLE_KEY and DEMO_USER_PASSWORD (12+ chars, upper/lower/digit).");
  process.exit(1);
}

const admin = createClient(url, serviceKey, { auth: { persistSession: false, autoRefreshToken: false } });

type Role = "customer" | "support" | "admin";

const CUSTOMERS = [
  { name: "Avery Lindqvist", phone: "+1 555 0101", address: "12 Maple Avenue", city: "Springfield", postal: "62701" },
  { name: "Jordan Okafor", phone: "+1 555 0102", address: "48 Harbor Street", city: "Riverton", postal: "82501" },
  { name: "Casey Moreau", phone: "+1 555 0103", address: "7 Lakeview Road", city: "Lakeside", postal: "92040" },
  { name: "Riley Tanaka", phone: "+1 555 0104", address: "301 Cedar Lane", city: "Hillview", postal: "40291" },
  { name: "Morgan Castillo", phone: "+1 555 0105", address: "95 Orchard Way", city: "Brookfield", postal: "53005" },
  { name: "Quinn Halvorsen", phone: "+1 555 0106", address: "2 Fjord Court", city: "Fairhaven", postal: "02719" },
] as const;

const STAFF = [
  { name: "Sam Rivera", email: "support@demo.acme-bank.example", role: "support" },
  { name: "Alex Morgan", email: "admin@demo.acme-bank.example", role: "admin" },
] as const;

async function findUserId(email: string): Promise<string | null> {
  for (let page = 1; page <= 10; page++) {
    const { data, error } = await admin.auth.admin.listUsers({ page, perPage: 200 });
    if (error) throw error;
    const hit = data.users.find((u) => u.email?.toLowerCase() === email.toLowerCase());
    if (hit) return hit.id;
    if (data.users.length < 200) return null;
  }
  return null;
}

async function ensureUser(email: string, fullName: string, role: Role): Promise<string> {
  const existing = await findUserId(email);
  if (existing) {
    const { error } = await admin.auth.admin.updateUserById(existing, { password: demoPassword, app_metadata: { role } });
    if (error) throw error;
    return existing;
  }
  const { data, error } = await admin.auth.admin.createUser({
    email,
    password: demoPassword,
    email_confirm: true,
    app_metadata: { role },
    user_metadata: { full_name: fullName },
  });
  if (error) throw error;
  return data.user.id;
}

async function removeStoredStatements(userId: string) {
  const { data } = await admin.storage.from("statements").list(userId, { limit: 1000 });
  if (data && data.length > 0) await admin.storage.from("statements").remove(data.map((f) => `${userId}/${f.name}`));
}

async function main() {
  for (const s of STAFF) await ensureUser(s.email, s.name, s.role);

  for (const [i, c] of CUSTOMERS.entries()) {
    const email = `customer${i + 1}@demo.acme-bank.example`;
    const userId = await ensureUser(email, c.name, "customer");
    const { error } = await admin.rpc("seed_demo_profile", {
      p_user_id: userId,
      p_full_name: c.name,
      p_email: email,
      p_phone: c.phone,
      p_address_line1: c.address,
      p_city: c.city,
      p_postal_code: c.postal,
    });
    if (error) throw error;
    await removeStoredStatements(userId);
  }

  const { error: resetError } = await admin.rpc("sim_reset_demo_data", { p_actor: null });
  if (resetError) throw resetError;

  const { count } = await admin.from("ledger_entries").select("id", { count: "exact", head: true });
  console.log(`Demo data ready: ${CUSTOMERS.length} customers, 2 staff users, ${count ?? "?"} ledger entries.`);
  console.log("Sign in with customer1..6@demo.acme-bank.example, support@... or admin@demo.acme-bank.example and DEMO_USER_PASSWORD.");
}

main().catch((err) => {
  console.error("Seeding failed:", err instanceof Error ? err.message : err);
  process.exit(1);
});
